function subarraySum(nums, k) {
  const seen = new Map([[0, 1]]);   // prefix sum -> how many times it occurred
  let prefix = 0, count = 0;
  for (const x of nums) {
    prefix += x;
    count += seen.get(prefix - k) ?? 0;   // earlier prefixes that leave exactly k
    seen.set(prefix, (seen.get(prefix) ?? 0) + 1);
  }
  return count;
}

class Solution {
    public int subarraySum(int[] nums, int k) {
        Map<Integer, Integer> seen = new HashMap<>();   // prefix sum -> how many times it occurred
        seen.put(0, 1);
        int prefix = 0, count = 0;
        for (int x : nums) {
            prefix += x;
            count += seen.getOrDefault(prefix - k, 0);   // earlier prefixes that leave exactly k
            seen.merge(prefix, 1, Integer::sum);
        }
        return count;
    }
}

class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        unordered_map<int, int> seen{{0, 1}};   // prefix sum -> how many times it occurred
        int prefix = 0, count = 0;
        for (int x : nums) {
            prefix += x;
            auto it = seen.find(prefix - k);     // earlier prefixes that leave exactly k
            if (it != seen.end()) count += it->second;
            seen[prefix]++;
        }
        return count;
    }
};
